import { Icon, Tooltip } from "@kit/index.js";
import { useLocalized } from "travel-platform";
import styles from "./FilterPanel.module.css";

export function FilterInfo({ tooltip }) {
    const localized = useLocalized();
    return (
        <Tooltip text={localized(tooltip.body)}>
            <span className={styles.info} tabIndex={0} aria-label={localized(tooltip.title)}><Icon name="info" size="small" color="alt" /></span>
        </Tooltip>
    );
}
