import { createContext, useContext, useId, useMemo } from "react";
import { Text } from "@kit/index.js";
import { LocalizedText } from "travel-platform";
import styles from "./FilterPanel.module.css";

const FilterGroupContext = createContext(null);

// The group a filter control belongs to.
export function useFilterGroup() {
    return useContext(FilterGroupContext);
}

export function FilterGroupFrame({ group, children }) {
    const id = useId();
    const value = useMemo(() => ({ field: group.field, position: group.position, labelId: id }), [group.field, group.position, id]);
    return (
        <FilterGroupContext.Provider value={value}>
            <section className={styles.group} aria-labelledby={id} data-testid="filters-group" data-filters-group={group.field}>
                <div className={styles.groupHeader}>
                    <Text as="h3" id={id} variant="strong_2"><LocalizedText value={group.title} /></Text>
                    {group.subtitle ? <Text variant="small_1" color="alt"><LocalizedText value={group.subtitle} /></Text> : null}
                </div>
                {children}
            </section>
        </FilterGroupContext.Provider>
    );
}
