import { Button, Image } from "@kit/index.js";
import { LocalizedText, useTrack, useTranslation } from "travel-platform";
import styles from "./FilterPanel.module.css";

// The map entry point. The map itself is out of the workload's scope.
export function MapTeaser({ preview }) {
    const t = useTranslation();
    const track = useTrack();
    return (
        <div className={styles.map} data-testid="map-trigger">
            <Image src={preview.image.url} width={preview.image.width} height={preview.image.height} alt={t("filters.map_alt")} ratio="16 / 9" className={styles.mapImage} />
            <Button variant="primary" icon="pin" className={styles.mapButton} onClick={() => track("map.open_attempt")}><LocalizedText value={preview.label} /></Button>
        </div>
    );
}
