import { useCallback } from "react";
import { Stack, Stepper } from "@kit/index.js";
import { useLocalized, useSearchState } from "travel-platform";

function StepperFilter({ stepper }) {
    const localized = useLocalized();
    const { navigate } = useSearchState();
    const onChange = useCallback((value) => navigate((state) => ({
        ...state,
        page: 0,
        filters: [...state.filters.filter((f) => !f.startsWith(`${stepper.urlPrefix}=`)), ...(value ? [`${stepper.urlPrefix}=${value}`] : [])],
    }), "stepper"), [navigate, stepper.urlPrefix]);
    return <Stepper label={localized(stepper.label)} a11yLabel={localized(stepper.a11yLabel)} value={stepper.value} min={stepper.min} max={stepper.max} onChange={onChange} testId={`filter-stepper-${stepper.field}`} />;
}

export function StepperFilterGroup({ control }) {
    return <Stack gap={1}>{control.steppers.map((stepper) => <StepperFilter key={stepper.field} stepper={stepper} />)}</Stack>;
}
